export const SEED_FILES: Record<string, string> = {
  "address-comments.prompt.md": "# Address the review comments on a pull request\n\nRe-read the pull request's review comments, make any changes that are actually requested,\nre-verify, and **stage a reply for the human to send**.\n\n## The rule that matters most\n\n**Do not post a comment on the pull request.** Not a reply, not a summary, not an\nacknowledgement. Marcelo answers reviewers himself, in his own words — an auto-posted reply reads\nas his and is not.\n\nWhat you do instead: write the per-point reply as a draft and record where it is, so the board\nshows a **reply draft** pill he can read and then post himself.\n\nEditing the pull request **body** is still wanted — the description should stay true as the\nbranch changes, and the video belongs there.\n\n## What to do\n\n1. Read every review comment and every review state on the pull request.\n2. For each point: decide whether it asks for a change. If it does, make it in the checkout.\n3. If you changed anything: re-run the verification against the dev server, capture a fresh\n   video, and update the `### Screenshot/Video` section of the body.\n4. Write the reply draft — one short paragraph per point, saying what you did or why nothing\n   changed. Never a bare `#<number>` in it.\n5. Record:\n\n```\n$ROOT/job.sh \"<library>\" phase=Done replyUrl=<path> message=\"<one line: what changed>\"\n```\n\nIf nothing needed changing, say so in the draft and record it the same way.\n",
  "fix.prompt.md": "# Fix one Dependabot vulnerability\n\nYou are the vulnerability console's fix agent. Somebody pressed **Fix** on one library. Bump it,\nprove the bump did not break where it is used, and record what you did. **Do not open a pull\nrequest** — that is a separate button and a separate run.\n\n## Where you are\n\nEvery command you run lands inside this fix's workspace, at the path it already has. You do not\nneed to `kubectl exec`, `ssh` or `cd` anywhere unusual; `yarn`, `git` and `node` are simply there.\n\n- the checkout is `$WSD/src`, on the repository's default branch\n- `origin` is the upstream repository, `fork` is where branches are pushed. The fork belongs to\n  whoever owns the stored token, and it has been created already if it did not exist\n- `gh` and `jq` are on `$PATH`, `GH_TOKEN` is in the environment of every command you run, and\n  git has a credential helper — so `gh` and `git push` work without you setting anything up\n- the dev server is **already running** and supervised. Never start a second one — the pod's\n  memory limit fits one, and two have OOM-killed the container out from under a run. Its URL is\n  in the job; a branch you check out is serving within a minute or two of compiling.\n\n## ⛔ You do not get woken up\n\nYou run one-shot. There is no notification, no wake-up, no re-invocation. The moment you stop to\n\"wait for a background task\" or \"await completion\", the run ends and everything you did is lost.\n\nRun every slow command **synchronously in the foreground**. If one might time out, block inline\nwith a single foreground loop over its log until a done marker appears. Never hand work to a\nbackground task and yield.\n\nDo **not** run the whole monorepo's `yarn lint` or `yarn test` — that is the pull request's CI\njob, it is slow, and it will strand you.\n\n## 1. Decide whether to fix, and on which branch\n\nA package can need fixing more than once over time, so branches are **numbered** and every\nre-fix gets its own. **Never reuse or force-push a branch that already has a pull request** —\nthat corrupts the earlier one and makes the new fix link to it.\n\nList what already exists:\n\n```\ngh pr list --repo <fork> --state all --json number,state,title,headRefName \\\n  | jq '[.[] | select(.title | test(\"<library>\"; \"i\"))]'\ngh api repos/<fork>/branches --paginate --jq '.[].name' | grep -E \"/<library>(-|$)\"\n```\n\nThen:\n\n- **an open pull request of ours already covers every still-open line** — stop, and record\n  `phase=Done message=\"already covered by pull request <n>\"`. Do not open another.\n- **an open pull request exists but does not cover this case** (it fixed a different manifest or\n  major line) — this is a separate fix: take the next free numbered branch.\n- **only merged pull requests exist and the advisory is open again** — always a new numbered\n  branch. Never touch the merged one's.\n- **nothing exists** — fix it on the base branch name.\n\nBranch names: `dependabot/npm_and_yarn/multi/<library>` for the first fix, then `<library>-1`,\n`<library>-2`, … — the first name not already in use.\n\n## 2. Make the fix\n\nStart from a clean tree on the repository's default branch, then bump the vulnerable dependency\nacross **every** manifest it touches and regenerate each lockfile.\n\n**Prefer a real update; a `resolutions` override is the last resort.** When a stale lockfile\nmerely holds a transitive at an old patch and the consuming range already admits a patched\nversion, `yarn upgrade <library>` lets it climb in place. Reach for a root `resolutions` pin only\nwhen neither an in-range update nor bumping the pinning parent can get there.\n\n### The three things reviewers actually catch\n\n1. **Cover every affected manifest, enumerated from the LIVE alerts** — not from the board,\n   which can be hours old:\n   ```\n   gh api repos/<repo>/dependabot/alerts --paginate \\\n     --jq '.[]|select(.state==\"open\")|select(.security_vulnerability.package.name==\"<library>\")|.dependency.manifest_path' \\\n     | sort -u\n   ```\n   Then grep the repository for every other `yarn.lock` pinning the vulnerable range. Bump them\n   all — root, `shell/`, **`cypress/`**, `storybook/`, `docusaurus/`, `pkg/*`. `cypress/yarn.lock`\n   is the commonly missed one.\n\n2. **Each affected major line needs that line's own first patched version.** They differ per\n   line: one advisory can require `1.1.16` *and* `2.1.2` *and* `5.0.7`, and a lower patch in one\n   line can still be vulnerable. Read each alert's `vulnerable_version_range` and\n   `first_patched_version`, and confirm the consuming `^x.y` ranges admit what you resolved to.\n\n3. **Introduce no new vulnerable package.** After regenerating, diff each lockfile for *added*\n   entries and check every newly added package and version — including a **different** package\n   the resolver pulled in (the classic is `braces < 3.0.3`). If the regeneration added a\n   vulnerable one, pin it forward, reinstall, and re-diff until the net change adds zero\n   vulnerabilities.\n\n### The lockfile will refuse to change\n\nThe checkout carries a root `.yarnrc` containing `--frozen-lockfile true`, and it is inherited by\nevery subdirectory. `yarn install` will install into `node_modules` and leave `yarn.lock`\nuntouched, so the bump appears to do nothing. Move the root `.yarnrc` aside, clear the package\nfrom `node_modules` and remove `.yarn-integrity`, install, then put `.yarnrc` back. Look for\n`success Saved lockfile.` and confirm the new version in the lock. **Never commit a `.yarnrc`\nchange.**\n\nCommit **only** `package.json` and `yarn.lock` files. No attribution trailers, no co-author\nlines, and no pull request or issue numbers in the message.\n\nRecord the branch as soon as it is pushed:\n\n```\n$ROOT/job.sh \"<library>\" branch=<branch>\n```\n\n## 3. Prove it still works\n\nThe point is not that it builds — it is that the place this library is actually used still\nbehaves. Grep the checkout for where it is imported, pick two to four real interactions that\nexercise it, and drive them in the browser against the running dev server.\n\nUse the browser that is already in this pod at `$VULN_BROWSER_CDP` — connect over CDP, do not\ninstall a browser. Capture an annotated video and take screenshots of each check.\n\nWrite the verification up as numbered checks, each ending ✅ or ❌, followed by a one-line\nverdict. Then record it:\n\n```\n$ROOT/job.sh \"<library>\" phase=Fixed previewUrl=<url> videoUrl=<path> infoUrl=<path> \\\n  message=\"<one line: what was bumped, in how many manifests, and what was verified>\"\n```\n\nIf a check fails, that is a real result: record `phase=Failed` with what broke. A fix that\nbreaks the feature is worse than the advisory.\n\n## What you must not do\n\n- do not open a pull request\n- do not comment on anything on GitHub\n- do not touch any repository other than the checkout in your workspace\n- do not start a second dev server\n",
  "gather.mjs": "#!/usr/bin/env node\n// Gather the Dependabot picture for one repository: every alert, Dependabot's own pull\n// requests, and ours.\n//\n// Dependency-free and shell-free on purpose. This runs inside the agents pod, a stock\n// `node:24` with neither `jq` nor `gh` in it, so the laptop pipeline it replaces\n// (scripts/gather-vulnerabilities.sh, which is `gh api | jq` from end to end) is re-expressed\n// in the one runtime the pod is guaranteed to have.\n//\n// It writes ALL alert states, not just the open ones. The board needs the closed ones to show\n// what we shipped, and - more importantly - closing is the ONLY thing that moves a row out of\n// the actionable list. A gather that dropped them would leave the board unable to tell \"fixed\"\n// from \"never seen\".\n\nimport { readFileSync, writeFileSync } from 'node:fs';\n\nconst REPO = process.env.VULN_REPO || 'rancher/dashboard';\n\n/**\n * The package this repository gets most of its tree from, if it has one.\n *\n * Empty for a repository that is its own tree. Set, it turns on the lockfile walk below.\n */\nconst OWNER_PACKAGE = process.env.OWNER_PACKAGE || '';\nconst OUT = process.env.OUT || './snapshot.json';\nconst API = process.env.GITHUB_API || 'https://api.github.com';\n\nfunction fail(message) {\n  process.stderr.write(`gather: ${ message }\\n`);\n  process.exit(1);\n}\n\n/**\n * The token, read from a file rather than the environment.\n *\n * A pod is a place where `ps` and `/proc/<pid>/environ` are readable, and this one is shared:\n * every conversation in it runs as the same user. A token on a command line or in an exported\n * variable is a token every pane can read for as long as the process lives. The file is written\n * 0600, read once here, and removed when the run ends.\n */\nfunction token() {\n  const file = process.env.CREDS_FILE;\n\n  if (!file) {\n    return process.env.GH_TOKEN || '';\n  }\n\n  try {\n    return JSON.parse(readFileSync(file, 'utf8')).GH_TOKEN || '';\n  } catch (e) {\n    fail(`could not read the credentials at ${ file }: ${ e?.message || e }`);\n  }\n}\n\nconst GH_TOKEN = token();\n\nif (!GH_TOKEN) {\n  fail('GH_TOKEN is not set. Dependabot alerts cannot be read without it.');\n}\n\nconst HEADERS = {\n  Authorization: `Bearer ${ GH_TOKEN }`,\n  Accept:        'application/vnd.github+json',\n  'User-Agent':  'vuln-console',\n};\n\nasync function request(url, what) {\n  let resp;\n\n  try {\n    resp = await fetch(url, { headers: HEADERS });\n  } catch (e) {\n    throw new Error(`${ what }: ${ e?.message || e }`, { cause: e });\n  }\n\n  const text = await resp.text();\n\n  if (!resp.ok) {\n    const detail = text.slice(0, 300).replace(/\\s+/g, ' ').trim();\n\n    throw new Error(`${ what }: HTTP ${ resp.status }${ detail ? ` - ${ detail }` : '' }`);\n  }\n\n  try {\n    return { body: JSON.parse(text), link: resp.headers.get('link') || '' };\n  } catch {\n    throw new Error(`${ what }: the answer was not JSON`);\n  }\n}\n\n/** Follow `Link: rel=\"next\"` rather than counting pages - GitHub decides where the end is. */\nasync function paginate(url, what) {\n  const all = [];\n  let next = url;\n\n  while (next) {\n    const { body, link } = await request(next, what);\n\n    if (!Array.isArray(body)) {\n      throw new Error(`${ what }: expected a list, got ${ typeof body }`);\n    }\n\n    all.push(...body);\n\n    const more = /<([^>]+)>;\\s*rel=\"next\"/.exec(link);\n\n    next = more ? more[1] : null;\n  }\n\n  return all;\n}\n\nfunction severityOf(value) {\n  const known = ['critical', 'high', 'medium', 'low'];\n\n  return known.includes(value) ? value : 'low';\n}\n\nasync function fetchAlerts() {\n  // No `state` filter, deliberately. The parameter takes a comma-separated list of the four\n  // real states and has no \"all\" - and an unrecognised value is not an error, it is an empty\n  // list. Asking for `state=all` returns zero alerts with HTTP 200, which is indistinguishable\n  // from a repository that has none.\n  const raw = await paginate(\n    `${ API }/repos/${ REPO }/dependabot/alerts?per_page=100`,\n    'reading the Dependabot alerts',\n  );\n\n  // Trimmed, because this ends up in a ConfigMap and a ConfigMap holds a megabyte. The full\n  // record for all 969 of rancher/dashboard's alerts is 521 KiB, which is half the ceiling on a\n  // list that only grows - so the snapshot carries what the BOARD reads and nothing else:\n  //\n  //   * `url` is derived (`<repo>/security/dependabot/<id>`), not stored.\n  //   * the vulnerable range, scope and relationship are not stored at all. They belong to\n  //     fixing, and the fix prompt already enumerates them from the LIVE alerts rather than the\n  //     snapshot - precisely because a snapshot can be hours old and a manifest list must not be.\n  //   * a CLOSED alert keeps only what the shipped list shows. 959 of the 969 are closed, and\n  //     what they are for is \"we fixed this\" - not the advisory text.\n  return raw.map((a) => {\n    const open = a.state === 'open';\n    const alert = {\n      id:       a.number,\n      library:  a.security_vulnerability?.package?.name || a.dependency?.package?.name || '?',\n      ghsa:     a.security_advisory?.ghsa_id || '',\n      severity: severityOf(a.security_advisory?.severity),\n      manifest: a.dependency?.manifest_path || '',\n      state:    a.state,\n      patched:  a.security_vulnerability?.first_patched_version?.identifier || null,\n      fixedAt:  a.fixed_at || null,\n    };\n\n    if (!open) {\n      return alert;\n    }\n\n    return {\n      ...alert,\n      ecosystem: a.security_vulnerability?.package?.ecosystem || 'npm',\n      cve:       a.security_advisory?.cve_id || null,\n      summary:   a.security_advisory?.summary || '',\n      createdAt: a.created_at,\n    };\n  });\n}\n\nfunction normalisePr(pr) {\n  return {\n    number:      pr.number,\n    url:         pr.html_url,\n    title:       pr.title || '',\n    headRefName: pr.head?.ref || '',\n    status:      pr.merged_at ? 'merged' : (pr.state === 'closed' ? 'closed' : 'open'),\n    author:      pr.user?.login || '',\n    createdAt:   pr.created_at,\n    mergedAt:    pr.merged_at || null,\n    videoUrl:    videoIn(pr.body || ''),\n  };\n}\n\n/**\n * A verification video already attached to a pull request body.\n *\n * Detecting it means the board's recording pill survives losing our own record of the run -\n * the pull request is the durable copy, and a GitHub-hosted URL is the published one.\n */\nfunction videoIn(body) {\n  const found = /https:\\/\\/github\\.com\\/user-attachments\\/assets\\/[0-9a-f-]+/i.exec(body);\n\n  return found ? found[0] : null;\n}\n\n/**\n * Our pull requests, in one GraphQL search.\n *\n * Not by paging `/pulls?state=closed`: rancher/dashboard has tens of thousands and the ones\n * that matter are a few hundred by one author. Not by the REST search either - that returns\n * issue records carrying neither the head branch nor a body, so every hit needed a second\n * call and a few hundred of those take longer than the whole rest of the gather. GraphQL\n * answers the question and returns the fields in the same request.\n *\n * Both fields it adds are load-bearing: a closed alert is attributed to a merge by TIMING, and\n * the branch is the fallback when a title says nothing.\n */\n/**\n * Who the stored token belongs to.\n *\n * Everything \"ours\" is defined by this and not by a name written into the extension: our pull\n * requests are the ones this account authored, and our fork is this account's fork. A hard-coded\n * login makes an extension that works for exactly one person and fails at `git push` for\n * everybody else, three minutes into a run.\n */\nasync function tokenOwner() {\n  const { body } = await request(`${ API }/user`, 'identifying the stored token');\n\n  if (!body?.login) {\n    throw new Error('identifying the stored token: the answer carried no login');\n  }\n\n  return body.login;\n}\n\nasync function fetchOurPulls(owner) {\n  const query = `repo:${ REPO } author:${ owner } is:pr`;\n  const found = [];\n  let cursor = null;\n\n  for (;;) {\n    const page = await graphql(\n      `query($q: String!, $after: String) {\n         search(query: $q, type: ISSUE, first: 100, after: $after) {\n           pageInfo { hasNextPage endCursor }\n           nodes {\n             ... on PullRequest {\n               number url title headRefName state createdAt mergedAt body\n               author { login }\n             }\n           }\n         }\n       }`,\n      { q: query, after: cursor },\n    );\n    const { nodes = [], pageInfo = {} } = page.search || {};\n\n    found.push(...nodes.filter((n) => n && n.number));\n\n    if (!pageInfo.hasNextPage) {\n      break;\n    }\n\n    cursor = pageInfo.endCursor;\n  }\n\n  return found\n    .map((n) => ({\n      number:      n.number,\n      url:         n.url,\n      title:       n.title || '',\n      headRefName: n.headRefName || '',\n      status:      n.mergedAt ? 'merged' : (n.state === 'CLOSED' ? 'closed' : 'open'),\n      author:      n.author?.login || '',\n      createdAt:   n.createdAt,\n      mergedAt:    n.mergedAt || null,\n      videoUrl:    videoIn(n.body || ''),\n    }))\n    .filter((p) => p.status !== 'closed');\n}\n\nasync function graphql(query, variables) {\n  let resp;\n\n  try {\n    resp = await fetch(`${ API }/graphql`, {\n      method:  'POST',\n      headers: { ...HEADERS, 'Content-Type': 'application/json' },\n      body:    JSON.stringify({ query, variables }),\n    });\n  } catch (e) {\n    throw new Error(`searching for our pull requests: ${ e?.message || e }`, { cause: e });\n  }\n\n  const text = await resp.text();\n\n  if (!resp.ok) {\n    throw new Error(`searching for our pull requests: HTTP ${ resp.status } - ${ text.slice(0, 300) }`);\n  }\n\n  const body = JSON.parse(text);\n\n  // GraphQL answers 200 with an `errors` array, so a failure here looks like a success to\n  // anything that only checks the status.\n  if (body.errors?.length) {\n    throw new Error(`searching for our pull requests: ${ body.errors.map((e) => e.message).join('; ') }`);\n  }\n\n  return body.data;\n}\n\n/** Dependabot's own open pull requests - the \"there is already one upstream\" signal. */\nasync function fetchDependabotPulls() {\n  const open = await paginate(\n    `${ API }/repos/${ REPO }/pulls?state=open&per_page=100`,\n    'reading the open pull requests',\n  );\n\n  return open.map(normalisePr).filter((p) => p.author === 'dependabot[bot]');\n}\n\n// ── Who owns a vulnerable library ──────────────────────────────────────────────────────────\n\n/**\n * Parse a yarn v1 lockfile into `spec -> { version, deps }`.\n *\n * The keys are exactly the `name@range` specs a package asks for, which is what makes the walk\n * below simple: a dependency's declared range IS the key of the entry that satisfies it, so\n * nothing has to resolve semver.\n */\nfunction parseLock(text) {\n  const entries = new Map();\n  let specs = null;\n  let version = '';\n  let deps = [];\n  let inDeps = false;\n\n  const flush = () => {\n    if (specs) {\n      for (const spec of specs) {\n        entries.set(spec, { version, deps });\n      }\n    }\n\n    specs = null;\n    version = '';\n    deps = [];\n    inDeps = false;\n  };\n\n  for (const raw of text.split('\\n')) {\n    if (!raw.trim() || raw.startsWith('#')) {\n      continue;\n    }\n\n    const indent = raw.length - raw.trimStart().length;\n    const line = raw.trim();\n\n    if (indent === 0) {\n      flush();\n      specs = line.replace(/:$/, '').split(',').map((part) => part.trim().replace(/^\"|\"$/g, ''));\n      continue;\n    }\n\n    if (indent === 2) {\n      inDeps = /^(dependencies|optionalDependencies):$/.test(line);\n\n      const found = /^version \"?([^\"]+)\"?$/.exec(line);\n\n      if (found) {\n        version = found[1];\n      }\n      continue;\n    }\n\n    if (indent >= 4 && inDeps) {\n      const found = /^\"?(@?[^\"\\s]+)\"?\\s+\"?([^\"]+)\"?$/.exec(line);\n\n      if (found) {\n        deps.push(`${ found[1] }@${ found[2] }`);\n      }\n    }\n  }\n\n  flush();\n\n  return entries;\n}\n\nfunction reachable(entries, roots) {\n  const seen = new Set();\n  const queue = [...roots];\n\n  while (queue.length) {\n    const spec = queue.pop();\n\n    if (seen.has(spec)) {\n      continue;\n    }\n\n    seen.add(spec);\n\n    const entry = entries.get(spec);\n\n    if (entry) {\n      queue.push(...entry.deps);\n    }\n  }\n\n  return seen;\n}\n\n/** Package names out of a set of `name@range` specs. */\nfunction namesOf(specs) {\n  const names = new Set();\n\n  for (const spec of specs) {\n    const at = spec.lastIndexOf('@');\n\n    if (at > 0) {\n      names.add(spec.slice(0, at));\n    }\n  }\n\n  return names;\n}\n\nasync function repoFile(path) {\n  const resp = await fetch(`${ API }/repos/${ REPO }/contents/${ path }`, {\n    headers: { ...HEADERS, Accept: 'application/vnd.github.raw' },\n  });\n\n  if (!resp.ok) {\n    throw new Error(`reading ${ path }: HTTP ${ resp.status }`);\n  }\n\n  return resp.text();\n}\n\n/**\n * Which vulnerable libraries are in the tree ONLY because of the owner package.\n *\n * Walked from the lockfile rather than guessed from the alert's `relationship`, because every\n * alert on a repository like this one is `transitive` - that field says the library is not a\n * direct dependency, not who pulled it in. rancher-ai-ui's `extract-zip` and `tmp` are\n * transitive too, and they come from Cypress and Jest; calling them shell's would be wrong in a\n * way somebody would only discover by trying to fix one.\n */\nasync function ownedLibraries() {\n  if (!OWNER_PACKAGE) {\n    return { ownerOnly: [], ownerVersion: '' };\n  }\n\n  const [manifest, lock] = await Promise.all([repoFile('package.json'), repoFile('yarn.lock')]);\n  const pkg = JSON.parse(manifest);\n  const direct = { ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) };\n  const entries = parseLock(lock);\n\n  const ownerRoots = [];\n  const otherRoots = [];\n\n  for (const [name, range] of Object.entries(direct)) {\n    (name === OWNER_PACKAGE ? ownerRoots : otherRoots).push(`${ name }@${ range }`);\n  }\n\n  if (!ownerRoots.length) {\n    return { ownerOnly: [], ownerVersion: '' };\n  }\n\n  const viaOwner = namesOf(reachable(entries, ownerRoots));\n  const viaOther = namesOf(reachable(entries, otherRoots));\n  const ownerOnly = [...viaOwner].filter((name) => !viaOther.has(name)).sort();\n\n  return { ownerOnly, ownerVersion: entries.get(ownerRoots[0])?.version || '' };\n}\n\nasync function main() {\n  // First, because everything \"ours\" is defined by it.\n  const owner = await tokenOwner();\n  const [alerts, dependabotPrs, ourPrs, owned] = await Promise.all([\n    fetchAlerts(),\n    fetchDependabotPulls(),\n    fetchOurPulls(owner),\n    // Never fatal: a board that cannot read its own lockfile is a board with no owner\n    // information, which is the same board it was before this existed - not a failed gather.\n    ownedLibraries().catch((e) => {\n      process.stderr.write(`gather: could not work out what ${ OWNER_PACKAGE } owns (${ e?.message || e })\\n`);\n\n      return { ownerOnly: [], ownerVersion: '' };\n    }),\n  ]);\n\n  // A transient failure must never be written as an empty snapshot. The console this replaces\n  // piped `gh api | jq ... || echo \"[]\"`, so a rate-limited page produced a valid 0-alert file\n  // that the watcher then reused for the rest of the day - the board simply went blank while\n  // the repository had 156 open alerts. Any failure above has already thrown; an empty result\n  // here is treated as one too.\n  if (!alerts.length) {\n    fail('no alerts came back at all. Refusing to write a snapshot that would blank the board.');\n  }\n\n  // Only the vulnerable libraries are worth storing, not the whole reachable set - the set is\n  // thousands of names and the board only ever asks about the ones it draws.\n  const vulnerable = new Set(alerts.map((a) => a.library));\n  const snapshot = {\n    gatheredAt: new Date().toISOString(),\n    repo:       REPO,\n    tokenLogin: owner,\n    alerts,\n    dependabotPrs,\n    ourPrs,\n    ...(OWNER_PACKAGE ? {\n      ownerPackage: OWNER_PACKAGE,\n      ownerVersion: owned.ownerVersion,\n      ownerOnly:    owned.ownerOnly.filter((name) => vulnerable.has(name)),\n    } : {}),\n  };\n\n  writeFileSync(OUT, JSON.stringify(snapshot));\n\n  const open = alerts.filter((a) => a.state === 'open').length;\n\n  const owns = snapshot.ownerOnly?.length\n    ? `, ${ snapshot.ownerOnly.length } only via ${ OWNER_PACKAGE } ${ snapshot.ownerVersion }`\n    : '';\n\n  process.stderr.write(\n    `gather: ${ alerts.length } alerts (${ open } open), ${ dependabotPrs.length } Dependabot pull requests, ${ ourPrs.length } by ${ owner }${ owns } -> ${ OUT }\\n`,\n  );\n}\n\nmain().catch((e) => fail(e?.message || String(e)));\n",
  "gather.sh": "#!/bin/sh\n# Refresh the board: gather the Dependabot picture and put it in the cluster.\n#\n# Deterministic from end to end - there is no agent in this path and nothing is judged. The old\n# console needed a watcher on somebody's laptop to do this on a timer; here it is a script the\n# extension runs in a pod it already has, and the result is a ConfigMap rather than a file in an\n# emptyDir that a pod rollout wiped.\n#\n# It resolves the token itself rather than being handed one. A token pasted into a page and\n# written through the exec socket is a token the browser held; read here, with the pod's own\n# ServiceAccount, at the moment it is needed, the browser never has it at all.\n#\n# usage: gather.sh <work-dir> <board-id> <repo> <token-key> [owner-package]\nset -e\n\nDIR=${1:?gather.sh needs a working directory}\nBOARD=${2:?gather.sh needs a board id}\nREPO=${3:?gather.sh needs a repository}\n# The Secret key holding the token of the person who asked for this. Per user, so a gather is\n# done as them and \"our pull requests\" means theirs.\nTOKEN_KEY=${4:?gather.sh needs the token key}\n# Optional: the package this repository gets most of its tree from. Empty for one that is its own.\nOWNER_PACKAGE=${5:-}\nSEED=$(dirname \"$0\")\n\n[ -d \"$DIR\" ] || { echo \"gather.sh: no such directory: $DIR\" >&2; exit 2; }\n\nNS=vuln-console\nSECRET=settings\n\n# kubectl as the pod rather than as whoever opened a terminal in it. shell.sh writes a kubeconfig\n# carrying the Rancher identity of the person who opened the pane, and that identity may not be\n# allowed to read these Secrets - the pod's ServiceAccount is. A KUBECONFIG naming nothing is\n# what sends kubectl to the in-cluster config.\nkube() {\n  KUBECONFIG=/dev/null kubectl \"$@\"\n}\n\nsecret_key() {\n  kube get secret \"$2\" -n \"$1\" -o \"jsonpath={.data.$3}\" 2>/dev/null | base64 -d 2>/dev/null | tr -d '\\r\\n'\n}\n\nGH_TOKEN=$(secret_key \"$NS\" \"$SECRET\" \"$TOKEN_KEY\")\n\nif [ -z \"$GH_TOKEN\" ]; then\n  echo \"gather.sh: no GitHub token is stored for this user. Set one from the Credentials dialog.\" >&2\n  exit 2\nfi\n\n# 0600 before anything is in it, so it is never briefly readable. Removed however this ends.\nCREDS=\"$DIR/creds.json\"\nSNAPSHOT=\"$DIR/snapshot.json\"\n\ncleanup() { rm -f \"$CREDS\"; }\ntrap cleanup EXIT INT TERM\n\n: > \"$CREDS\"\nchmod 600 \"$CREDS\"\n\n# Through node rather than printf, so a token containing a quote or a backslash is JSON-encoded\n# rather than pasted into a string and hoped for.\nGH_TOKEN=\"$GH_TOKEN\" node -e \\\n  'require(\"fs\").writeFileSync(process.argv[1], JSON.stringify({ GH_TOKEN: process.env.GH_TOKEN }))' \\\n  \"$CREDS\"\n\nCREDS_FILE=\"$CREDS\" OUT=\"$SNAPSHOT\" VULN_REPO=\"$REPO\" OWNER_PACKAGE=\"$OWNER_PACKAGE\" \\\n  node \"$SEED/gather.mjs\"\n\ncleanup\n\n# A ConfigMap holds a megabyte. A snapshot that does not fit has to fail as a gather somebody can\n# see, not as a kubectl error nobody reads.\nSIZE=$(wc -c < \"$SNAPSHOT\")\n\nif [ \"$SIZE\" -gt 950000 ]; then\n  echo \"gather.sh: the snapshot is $((SIZE / 1024)) KiB, over what a ConfigMap can hold\" >&2\n  exit 2\nfi\n\nkube get namespace \"$NS\" >/dev/null 2>&1 || kube create namespace \"$NS\" >/dev/null\n\n# Server-side apply, NOT the client-side default. A client-side `apply` records the whole object\n# it sent in a `kubectl.kubernetes.io/last-applied-configuration` annotation, and annotations are\n# capped at 256 KiB - so a snapshot large enough to be worth having is one the apiserver rejects\n# outright (\"metadata.annotations: Too long\"). Server-side apply keeps its bookkeeping in\n# managedFields instead, where there is no such limit.\n\nkube create configmap \"snapshot-$BOARD\" \\\n  --namespace \"$NS\" \\\n  --from-file=snapshot.json=\"$SNAPSHOT\" \\\n  --dry-run=client -o json |\n  node -e '\n    let raw = \"\";\n\n    process.stdin.on(\"data\", (c) => (raw += c));\n    process.stdin.on(\"end\", () => {\n      const cm = JSON.parse(raw);\n\n      cm.metadata.labels = {\n        \"vuln-console.rancher.io/owns\": \"true\",\n        \"vuln-console.rancher.io/board\": process.argv[1],\n      };\n      process.stdout.write(JSON.stringify(cm));\n    });\n  ' \"$BOARD\" |\n  kube apply --server-side --force-conflicts -f - >/dev/null\n\necho \"gather.sh: published a $((SIZE / 1024)) KiB snapshot for $BOARD ($REPO)\"\n",
  "job.sh": "#!/bin/sh\n# Record what a run achieved, as fields on its job.\n#\n# The agent calls this rather than composing kubectl itself, for the same reason the report\n# console has a publish script: the object name and the label are what the board selects on, so\n# a job written with a typo'd label is a job that exists and cannot be found.\n#\n# It MERGES. Each call sets the fields it is given and leaves the rest, so recording a branch\n# early and a pull request later does not erase the branch - which is the failure mode of every\n# \"write the whole file\" version of this.\n#\n# usage: job.sh <board> <library> phase=Done branch=... prNumber=123 message=\"...\"\nset -e\n\nBOARD=${1:?job.sh needs the board}\nLIBRARY=${2:?job.sh needs the library}\nshift 2\n\nNS=vuln-console\n\nkube() { KUBECONFIG=/dev/null kubectl \"$@\"; }\n\n# The object name, by the same rule the extension uses: lowercased, anything that is not a\n# letter or a digit becomes a hyphen. `@scope/name` is not a legal object name and this is only\n# an address - the record keeps the real library name in a field.\nNAME=job-$BOARD-$(printf '%s' \"$LIBRARY\" | tr '[:upper:]' '[:lower:]' | sed 's/[^a-z0-9]\\{1,\\}/-/g; s/^-*//; s/-*$//' | cut -c1-40)\n\nCURRENT=$(kube get configmap \"$NAME\" -n \"$NS\" -o \"jsonpath={.data.job\\.json}\" 2>/dev/null || true)\n\n# Read the current record, apply the assignments, write it back. Through node because the values\n# are arbitrary text - a message can contain a quote, a URL contains slashes - and sed would\n# mangle both.\nUPDATED=$(CURRENT=\"$CURRENT\" LIBRARY=\"$LIBRARY\" BOARD=\"$BOARD\" node -e '\n  const assignments = process.argv.slice(1);\n  let job = {};\n\n  try {\n    job = JSON.parse(process.env.CURRENT || \"{}\") || {};\n  } catch {\n    job = {};\n  }\n\n  job.library = job.library || process.env.LIBRARY;\n  job.board = job.board || process.env.BOARD;\n\n  // Numbers stay numbers and the empty string clears a field, so `prNumber=` is how a run says\n  // \"there is no pull request\" without writing the string \"null\" into the board.\n  for (const pair of assignments) {\n    const at = pair.indexOf(\"=\");\n\n    if (at < 1) {\n      continue;\n    }\n\n    const key = pair.slice(0, at);\n    const raw = pair.slice(at + 1);\n\n    if (raw === \"\") {\n      job[key] = null;\n    } else if (/^(prNumber|startedAt|updatedAt)$/.test(key)) {\n      job[key] = Number(raw);\n    } else if (key === \"vulnIds\") {\n      job[key] = raw.split(\",\").map((n) => Number(n.trim())).filter((n) => !Number.isNaN(n));\n    } else {\n      job[key] = raw;\n    }\n  }\n\n  job.updatedAt = Date.now();\n  process.stdout.write(JSON.stringify(job));\n' \"$@\")\n\n[ -n \"$UPDATED\" ] || { echo \"job.sh: refusing to write an empty job\" >&2; exit 1; }\n\nkube get namespace \"$NS\" >/dev/null 2>&1 || kube create namespace \"$NS\" >/dev/null\n\nprintf '%s' \"$UPDATED\" > /tmp/job-$$.json\n\nkube create configmap \"$NAME\" \\\n  --namespace \"$NS\" \\\n  --from-file=job.json=/tmp/job-$$.json \\\n  --dry-run=client -o json |\n  node -e '\n    let raw = \"\";\n\n    process.stdin.on(\"data\", (c) => (raw += c));\n    process.stdin.on(\"end\", () => {\n      const cm = JSON.parse(raw);\n\n      cm.metadata.labels = {\n        \"vuln-console.rancher.io/owns\": \"true\",\n        \"vuln-console.rancher.io/board\": process.argv[1],\n      };\n      process.stdout.write(JSON.stringify(cm));\n    });\n  ' \"$BOARD\" |\n  kube apply --server-side --force-conflicts -f - >/dev/null\n\nrm -f /tmp/job-$$.json\n\necho \"job.sh: recorded $*\"\n",
  "pr.prompt.md": "# Open the pull request for a verified fix\n\nThe fix is made, pushed and verified. Open the pull request for it, and nothing else.\n\n## Rules that are not negotiable\n\n- **Open it as a draft, and leave it a draft.** The human marks it ready for review themselves.\n  Never run `gh pr ready`.\n- **Never write a bare `#<number>`** in the body. GitHub auto-links it to an unrelated pull\n  request or issue, which is a false cross-reference somebody then has to explain. Use a full URL\n  or a link label.\n- **No attribution trailers** and no reviewer names in the commit history.\n\n## What to do\n\n1. Confirm the branch is pushed and its diff is what you expect. Diff it against **upstream's**\n   default branch, never the fork's own — the fork's is chronically stale, and judging by it\n   makes a clean fix look like it carries half the repository with it.\n\n2. Open the draft pull request from the fix branch. Title it the way Dependabot does:\n   `Bump <library> from <old> to <new>` — the board reads the library out of that title, and a\n   title it cannot read is a row that loses its pull request.\n\n3. The body carries: what was bumped and in which manifests, a `### Vulnerabilities fixed`\n   section listing each advisory by GHSA id with a full URL, and a `### Screenshot/Video`\n   section. Put the verification video's URL **on its own line** — that is what makes GitHub\n   render a player rather than a link.\n\n4. Request the reviewers the board has selected, if any are given to you.\n\n5. Record it, including the alert ids this pull request covers — that record is what ties them\n   together afterwards, and it beats any guess the board could make from titles:\n\n```\n$ROOT/job.sh \"<library>\" phase=Done prUrl=<url> prNumber=<n> vulnIds=<id,id,id>\n```\n\n## What you must not do\n\n- do not mark it ready for review\n- do not merge it\n- do not comment on it\n",
  "publish.prompt.md": "# Attach a staged recording to its pull request\n\nThe recording exists and the pull request exists; put one in the other.\n\n1. Upload the video as a GitHub user-attachment so it renders as an inline player. A release\n   asset link renders as a link, not a player, which is not what this is for.\n2. Splice it into the pull request body's `### Screenshot/Video` section, **on its own line**.\n3. Leave the staged copy alone until the upload is confirmed, then record the published URL:\n\n```\n$ROOT/job.sh \"<library>\" videoUrl=<github-url>\n```\n\nDo not comment on the pull request. Do not mark it ready for review.\n",
  "record.prompt.md": "# Capture the verification recording again\n\nThe fix exists but its recording does not, or needs redoing. Produce it, and change nothing else.\n\n1. Check out the fix branch in the workspace and let the supervised dev server compile it. Do not\n   start a second server.\n2. Grep the checkout for where the library is used and pick two to four real interactions that\n   exercise it.\n3. Drive them against the dev server through the browser already in this pod\n   (`$VULN_BROWSER_CDP`), connecting over CDP. Capture an annotated video and screenshots.\n4. Write the checks up as a numbered list, each ending ✅ or ❌, then a one-line verdict.\n5. Record:\n\n```\n$ROOT/job.sh \"<library>\" videoUrl=<path> infoUrl=<path> message=\"<one line verdict>\"\n```\n\nDo not change the branch, do not open or edit a pull request.\n",
  "resolve-conflict.prompt.md": "# Rebase a fix branch onto the latest default branch\n\nThe pull request has drifted from its base, or conflicts with it. Bring it up to date.\n\n## What to do\n\n1. Fetch upstream and check whether the branch actually conflicts. GitHub computes mergeability\n   asynchronously, so a \"conflict\" flag can be one poll stale — look for yourself.\n2. If it is clean and merely behind, rebase it onto the latest default branch.\n3. If it conflicts, rebase and **re-apply the fix** rather than resolving by hand where the\n   resolution is a lockfile: regenerate the lockfiles from the rebased tree using the recipe in\n   the fix prompt, so what lands is a real resolution and not a merge artefact.\n4. Re-check that no vulnerable version remains and that the diff adds no new vulnerable package.\n5. Force-push **only this branch**, and only when it is the branch this job owns.\n6. Record:\n\n```\n$ROOT/job.sh \"<library>\" phase=Done message=\"<one line: rebased onto <sha>, lockfiles regenerated>\"\n```\n\n## What you must not do\n\n- do not force-push any branch other than this one\n- do not comment on the pull request\n- do not mark it ready for review\n",
  "workspace/boot.sh": "#!/bin/sh\n# Bring one fix workspace up: a rancher/dashboard checkout with its dependencies installed and\n# the dev server supervised on top of it.\n#\n# The container's main process ends up being the supervisor, not the server, because a fix run\n# does things that kill a dev server - switches branch, regenerates a lockfile, runs a build -\n# and a pod whose main process was the server would restart on each of those and take the run's\n# terminal with it.\n#\n# `${install}`, `${repo}` and `${port}` are apps-plus substitutions, filled in when the App is\n# rendered. Everything written `$LIKE_THIS` is ordinary shell and is left alone: apps-plus only\n# substitutes the braced form, and only for names its App declares.\nset -e\n\n# Force apt onto IPv4 before anything runs one. The node has no working IPv6 route to the Debian\n# mirror, so an `apt-get update` left alone resolves an IPv6 address and hangs on it for minutes\n# while holding the apt lock - which is how a workspace comes up with no tmux and no terminal.\nmkdir -p /etc/apt/apt.conf.d\nprintf 'Acquire::ForceIPv4 \"true\";\\nAcquire::Retries \"3\";\\n' > /etc/apt/apt.conf.d/99vuln-ipv4\n\nWS=/workspaces/${install}\nmkdir -p \"$WS/.home\"\nchown node:node \"$WS\" \"$WS/.home\" 2>/dev/null || true\n[ -f \"$WS/.owned\" ] || { chown -R node:node \"$WS\" 2>/dev/null; touch \"$WS/.owned\"; }\n\n# The browser sidecar mounts these as subPaths, and the kubelet creates a missing subPath as\n# root - leaving the seed unable to write into it.\nmkdir -p \"$WS/.a11y/opt\" \"$WS/.a11y/init\"\nchown -R node:node \"$WS/.a11y\" 2>/dev/null || true\n\n# What every workspace on this node shares rather than keeping its own copy. Measured before\n# this existed: Cypress 813 MB, yarn 749 MB, and a gigabyte of node_modules - most of a\n# workspace's 3 GB, per workspace.\nSHARED=/workspaces/.shared\nmkdir -p \"$SHARED/yarn\" \"$SHARED/cypress\" \"$SHARED/npm\" \"$SHARED/template\"\nchown node:node \"$SHARED\" \"$SHARED/yarn\" \"$SHARED/cypress\" \"$SHARED/npm\" \"$SHARED/template\" 2>/dev/null || true\n\n# tmux and kubectl, which the terminal needs. No claude: the conversation runs in the agents pod\n# and reaches this one through a tunnel, so a claude here is hundreds of megabytes of hostPath\n# that nothing executes.\n[ -f /seed/terminal-tools.sh ] \\\n  && (TOOLS_NO_CLAUDE=1 HOME_DIR=\"$WS/.home\" /bin/sh /seed/terminal-tools.sh >\"$WS/.terminal-tools.log\" 2>&1 &) \\\n  || true\n\n# What a recording and a lockfile bump need and the image lacks. Backgrounded so the dev server\n# is not a minute later for it; the lock timeout lets it wait for the tmux install above rather\n# than colliding with it.\n(command -v ffmpeg >/dev/null 2>&1 && command -v lsof >/dev/null 2>&1) || (\n  apt-get -o DPkg::Lock::Timeout=300 update -qq \\\n    && DEBIAN_FRONTEND=noninteractive apt-get -o DPkg::Lock::Timeout=300 install -y -qq \\\n      ffmpeg jq lsof iproute2 >\"$WS/.apt.log\" 2>&1 &\n) || true\n\n# /workspace-config, not /seed. This extension's scripts are mounted from its own ConfigMap;\n# /seed is the agents extension's, which is optional here and usually absent - so pointing at it\n# crash-looped the pod with \"cannot open /seed/checkout.sh\".\nexec setpriv --reuid=1000 --regid=1000 --init-groups /bin/sh /workspace-config/checkout.sh\n",
  "workspace/checkout.sh": "#!/bin/sh\n# The workspace's checkout and install, as the node user. Split from boot.sh so the privileged\n# half is short enough to read and this half can be run again by hand.\nset -e\n\nWS=/workspaces/${install}\nSHARED=/workspaces/.shared\n\nexport HOME=\"$WS/.home\"\nexport YARN_CACHE_FOLDER=\"$SHARED/yarn\"\nexport CYPRESS_CACHE_FOLDER=\"$SHARED/cypress\"\nexport npm_config_cache=\"$SHARED/npm\"\n\n# init + fetch rather than `git clone`, because clone refuses a non-empty directory and this one\n# is not reliably empty: the agent seed writes `.claude` into the checkout, and if that lands\n# first - a separate trigger racing this boot - a clone would fail and leave the pod serving\n# nothing.\nif [ ! -d \"$WS/src/.git\" ]; then\n  mkdir -p \"$WS/src\"\n  cd \"$WS/src\"\n  git init -q\n  git remote add origin https://github.com/${repo} 2>/dev/null || true\n  DEFAULT=$(git ls-remote --symref origin HEAD | sed -n 's@^ref: refs/heads/\\(.*\\)[[:space:]]HEAD@\\1@p')\n  git fetch --depth 1 origin \"$DEFAULT\"\n  git checkout -f -B \"$DEFAULT\" FETCH_HEAD\nfi\n\ncd \"$WS/src\"\n\n# The fork is where fixes are pushed, so it is a remote from the start rather than something the\n# agent has to remember to add. `upstream` is what a branch is diffed against - never the fork's\n# own master, which is chronically stale and makes a clean fix look like it carries half the\n# repository with it.\ngit remote add fork \"https://github.com/${fork}\" 2>/dev/null || true\ngit remote set-url fork \"https://github.com/${fork}\" 2>/dev/null || true\ngit remote add upstream \"https://github.com/${repo}\" 2>/dev/null || true\n\n# node_modules, hard-linked from a template of the same lockfile if this node already has one.\n# The files are the same inodes, so a second workspace's node_modules costs directory entries\n# and nothing else. Keyed by the lockfile hash, so a template is only ever used by a checkout\n# that would have installed exactly it.\nHASH=$(sha1sum yarn.lock 2>/dev/null | cut -c1-12)\n\nif [ -n \"$HASH\" ] && [ ! -d node_modules ] && [ -d \"$SHARED/template/$HASH/node_modules\" ]; then\n  cp -al \"$SHARED/template/$HASH/node_modules\" node_modules && touch .install-done\nfi\n\n[ -f .install-done ] || {\n  yarn install --mutex \"file:$SHARED/yarn/.mutex\" --network-timeout 600000\n  touch .install-done\n}\n\n# The first workspace to install a given lockfile leaves the template for the next one.\nif [ -n \"$HASH\" ] && [ -d node_modules ] && [ ! -d \"$SHARED/template/$HASH\" ]; then\n  mkdir -p \"$SHARED/template/$HASH\"\n  cp -al node_modules \"$SHARED/template/$HASH/node_modules\" || rm -rf \"$SHARED/template/$HASH\"\nfi\n\n# The injected vue config, copied INTO the checkout.\n#\n# vue-cli resolves it with `is-file-esm`, which walks up from the config's own path looking for a\n# package.json to decide whether it is ESM. Pointed at a file in a ConfigMap mount there is no\n# package.json above it, and it dies with \"Cannot read properties of undefined (reading\n# 'packageJson')\" - which is a dev server that never starts, on every repository.\n#\n# A dotfile so it is invisible to the repository's own tooling, and excluded from git so it can\n# never end up in a fix's diff.\ncp /workspace-config/vue.config.js \"$WS/src/.workspace.vue.config.js\"\ngrep -qxF '.workspace.vue.config.js' \"$WS/src/.git/info/exclude\" 2>/dev/null \\\n  || echo '.workspace.vue.config.js' >> \"$WS/src/.git/info/exclude\"\n\nexec /bin/bash /workspace-config/serve.sh ${port}\n",
  "workspace/serve.sh": "#!/bin/bash\n# The dev server, supervised: the container's process is this loop, not the server.\n#\n# A fix run does things that kill a dev server - switches branch, regenerates a lockfile, runs a\n# build. When the pod's main process was the server itself, each of those restarted the\n# container and took the run's terminal with it, mid-fix. So the server is restarted when it\n# exits, and left alone while something else holds the port.\nPORT=${1:-8005}\n\n# The boot script runs this from the checkout, so the tree is its parent - which is where the\n# log and the retarget file live.\nWS=${WS:-$(dirname \"$PWD\")}\nRETARGET=$WS/.dev-server.env\nLOG=$WS/.dev-server.log\n\necho \"$PORT\" > \"$WS/.dev-server.port\" 2>/dev/null || true\nexport PORT WS RETARGET LOG IONICE\n\nheld() {\n  node -e \"require('net').connect(Number(process.argv[1]),'127.0.0.1').on('connect',()=>process.exit(0)).on('error',()=>process.exit(1))\" \"$PORT\" 2>/dev/null\n}\n\n# Not all at once. Rancher's embedded k3s runs beside these servers, and when it restarts every\n# workspace pod restarts with it and every webpack compiles at the same moment: a dozen of them\n# on twelve cores, k3s's controllers fail to renew their lease, k3s exits, Rancher restarts -\n# and the herd forms again. So a server waits, with jitter so they do not all wake together,\n# while the node's one-minute load is above what the cores can carry.\nCORES=$(nproc 2>/dev/null || echo 4)\ngate() {\n  load=$(cut -d. -f1 /proc/loadavg 2>/dev/null || echo 0)\n  [ \"$load\" -le $(( CORES * 3 / 2 )) ]\n}\n\n# One dev server per pod, whoever started it. A second webpack is another two gigabytes at every\n# rebuild and the pod's limit is five, so an agent that starts its own gets the port until it is\n# done and this one comes back afterwards. Only node processes, matched by command line: a shell\n# or a grep that merely mentions the server would otherwise count and stop this one for nothing.\nservers() { pgrep -f \"^[^ ]*node .*vue-cli-service serve\" 2>/dev/null; }\nforeign() {\n  local p\n  for p in $(servers); do\n    [ \"$(ps -o pgid= -p \"$p\" 2>/dev/null | tr -d ' ')\" = \"$SERVER\" ] || echo \"$p\"\n  done\n}\n\nSERVER=\"\"\nstop_ours() {\n  if [ -n \"$SERVER\" ]; then\n    kill -TERM -- -\"$SERVER\" 2>/dev/null\n    wait \"$SERVER\" 2>/dev/null\n    SERVER=\"\"\n  fi\n}\ntrap \"stop_ours; exit 0\" TERM INT\n\nwhile :; do\n  if held || [ -n \"$(foreign)\" ]; then sleep 10; continue; fi\n\n  sleep $(( RANDOM % 20 ))\n\n  waited=0\n  while ! gate && [ \"$waited\" -lt 300 ]; do\n    [ \"$waited\" -eq 0 ] && echo \"[workspace] the node is busy; waiting to start the dev server\"\n    sleep 10\n    waited=$((waited + 10))\n  done\n\n  # Below the cluster's own processes: a compile that takes every core has taken k3s down with\n  # it on a busy node, and a slow first page is the better failure.\n  IONICE=\"\"\n  command -v ionice >/dev/null 2>&1 && IONICE=\"ionice -c 3\"\n\n  # What the server runs against can be changed without a new pod: writing the retarget file\n  # restarts it onto a different Rancher. Read in the server's own shell, so it replaces the\n  # pod's environment for the server alone.\n  STAMP=$(stat -c %Y \"$RETARGET\" 2>/dev/null || echo 0)\n  [ -f \"$RETARGET\" ] && echo \"[workspace] the dev server runs against $(grep '^API=' \"$RETARGET\" | cut -d= -f2-)\"\n\n  # setsid, so the server and everything it starts are one process group a stop can signal as a\n  # whole; tee, so the log is in the tree as well as in the pod's.\n  setsid bash -c 'if [ -f \"$RETARGET\" ]; then set -a; . \"$RETARGET\"; set +a; fi; nice -n 15 $IONICE env VUE_CLI_SERVICE_CONFIG_PATH=\"$WS/src/.workspace.vue.config.js\" yarn dev --port \"$PORT\" 2>&1 | tee \"$LOG\"' &\n  SERVER=$!\n\n  # `sleep & wait`, not `sleep`: a trap runs once the foreground command returns, and a stop\n  # that waited out the sleep left the server running for the check that followed.\n  while kill -0 \"$SERVER\" 2>/dev/null; do\n    sleep 10 & wait $!\n    if [ -n \"$(foreign)\" ]; then\n      echo \"[workspace] another dev server is running in this pod; standing down until it is gone\"\n      stop_ours; sleep 10; continue 2\n    fi\n    if [ \"$(stat -c %Y \"$RETARGET\" 2>/dev/null || echo 0)\" != \"$STAMP\" ]; then\n      echo \"[workspace] the dev server's target changed; restarting it\"\n      stop_ours; continue 2\n    fi\n  done\n\n  SERVER=\"\"\n  echo \"[workspace] the dev server exited; starting it again in 5s\"\n  sleep 5\ndone\n",
  "workspace/vue.config.js": "// Written by the Dev extension. See pkg/dev-extension/workspace-config.ts.\n//\n// This dev server is reached one of two ways, and everything below is the consequence of which.\n//\n//   - behind the apiserver's service proxy, at DEV_PROXY_PATH, on Rancher's own origin. The Host\n//     header is the proxy's, the TLS the browser sees is Rancher's, the prefix is stripped on the\n//     way in and has to be put back on every URL handed out.\n//   - at an origin of its own, on a node port, with no prefix at all.\n//\n// A dev server built for one does not work at the other: the router base is baked in. Which one\n// this is comes from DEV_PROXY_PATH being set or empty, and changing it restarts the pod.\n//\n// The second mode exists because of what the first one does to a dashboard. rancher/dashboard\n// builds its API URLs absolute from the page origin, so behind the prefix its /v1 and /v3 calls\n// never reach this dev server at all: they go to the Rancher this page was served from, using\n// that session, against that cluster. Measured, on a workspace with a Rancher of its own: two\n// requests arrived here and a hundred and thirty-six went to the host. An origin of its own is\n// the only thing that fixes it, because there is no browser-side API base to set.\nconst proxyPath = (process.env.DEV_PROXY_PATH || '').replace(/\\/$/, '');\n\n// The prefix on every in-app link, which has to be the path the page was loaded at. Set before\n// the shell's config runs, because the shell reads it out of the environment as it does.\nprocess.env.ROUTER_BASE = proxyPath ? proxyPath + '/' : '/';\n\n// The repo's own config, untouched in the checkout, rather than a reimplementation of it.\n// rancher/dashboard is a monorepo whose shell is ./shell rather than a node_modules package,\n// and which arguments its root config passes to that shell is the repo's business and changes\n// with the repo. Wrapping it means this file only has to know about the proxy. This file is\n// handed to vue-cli-service as VUE_CLI_SERVICE_CONFIG_PATH (see apps.ts, WORKSPACE_SCRIPT), so\n// it lives outside the checkout and the checkout's own vue.config.js is never rewritten: the\n// tree stays clean, a branch switch never trips over it, and nothing an agent commits carries it.\nconst base = require(require('path').join(process.cwd(), 'vue.config.js'));\n\n// The proxy rewrites absolute URLs in HTML as they pass through, which is what lets a naive UI\n// work behind it at all, so an asset URL that already carried the prefix would carry it twice.\n// index.html therefore asks for '/js/...' and lets the proxy add the prefix, while webpack's\n// runtime works its own base out from the script URL it was loaded from.\nbase.publicPath = 'auto';\n\nconst previousChainWebpack = base.chainWebpack;\n\nbase.chainWebpack = (webpackConfig) => {\n  if (typeof previousChainWebpack === 'function') {\n    previousChainWebpack(webpackConfig);\n  }\n\n  webpackConfig.plugin('html-index').tap((args) => {\n    args[0].publicPath = '/';\n\n    return args;\n  });\n};\n\nbase.devServer = {\n  ...base.devServer,\n\n  // Plain http only behind the proxy, where Rancher terminates TLS and will not talk to the\n  // shell's self-signed dev certificate on the way through.\n  //\n  // At its own origin the browser talks to this server directly, and http there is not a smaller\n  // problem than a certificate warning, it is a broken login: the shipped proxy sets\n  // x-forwarded-proto: https on every request it makes, so Rancher issues its session cookie with\n  // Secure, and a browser on http throws that cookie away. What that looks like is a login that\n  // returns 200 and a page that bounces straight back to the login form, which is what it did.\n  // So https here, with the shell's own certificate, and a warning to click through once.\n  ...(proxyPath ? { server: { type: 'http' } } : {}),\n\n  // Requests arrive with whatever Host the proxy chain last set, never this server's own.\n  // Without this the proxy answers 'Invalid Host header'.\n  allowedHosts: 'all',\n\n  // The proxy cannot rewrite URLs in a compressed body: the response comes back as a stream\n  // error and the browser shows a blank page.\n  compress: false,\n\n  // The prefix is stripped before a request lands here, so everything is served from the root.\n  devMiddleware: { publicPath: '/' },\n  static:        { publicPath: '/' },\n\n  // A deep link into the dashboard has to load the app rather than 404. disableDotRule matters\n  // in Rancher, where a route routinely carries a resource name with dots in it.\n  historyApiFallback: {\n    index:             '/index.html',\n    disableDotRule:    true,\n    htmlAcceptHeaders: ['text/html', 'application/xhtml+xml']\n  },\n\n  hot:             true,\n  webSocketServer: { type: 'ws', options: { path: '/ws' } },\n  client:          {\n    // Hot reload rides the same proxy when there is one, and the page's own origin when there is\n    // not. Either way this has to be written out, because the shell's config has an address of its\n    // own in it and that address is not where this server is.\n    //\n    // Behind the proxy only the path is ours; the rest are webpack-dev-server's \"infer it from\n    // window.location\" sentinels. 'auto' is one the *server* substitutes as it serves the client.\n    //\n    // Served at its own origin the sentinels are still needed, and leaving them out was a real\n    // bug rather than a tidy default. The shell's own config sets a fixed\n    // wss://localhost:8005/ws, which is right on a laptop running the dev server and wrong\n    // everywhere else: the browser then opened a hot-reload socket to whatever was on port 8005\n    // of the machine the browser is on, and displayed that server's compile errors over this\n    // dashboard. Seen here as a webpack overlay full of a completely different project's module\n    // resolution failures, sitting on top of the workspace's login form and swallowing clicks.\n    //\n    // 0.0.0.0 and 0 are webpack-dev-server's own \"take it from window.location\" sentinels. The\n    // protocol is written out rather than left as 'auto', because 'auto' is substituted by the\n    // server as it serves the client and is handed to the WebSocket constructor unchanged when\n    // the page was loaded directly. This server is https at its own origin, so wss.\n    webSocketURL: proxyPath ? {\n      protocol: 'auto',\n      hostname: '0.0.0.0',\n      port:     0,\n      pathname: proxyPath + '/ws'\n    } : {\n      protocol: 'wss',\n      hostname: '0.0.0.0',\n      port:     0,\n      pathname: '/ws'\n    },\n    // The compile-error overlay would cover the whole framed dashboard for whoever is looking\n    // when an edit fails to compile.\n    overlay: false\n  }\n};\n\nmodule.exports = base;\n",
  "workspace-setup.sh": "#!/bin/sh\n# Make a fix workspace able to do the work: give it a GitHub credential, the `gh` CLI, and a\n# fork to push to.\n#\n# This runs in the AGENTS pod, not the workspace, and that is the point. The agents pod's\n# ServiceAccount can read the token out of the Secret; the workspace's cannot, and should not -\n# it is a pod running a build. So the token is read here and handed across the one channel that\n# already exists between them, an exec into the workspace.\n#\n# The token is never on a command line. `kubectl exec` argv travels through the apiserver as URL\n# query parameters, which are logged; it goes over STDIN instead.\n#\n# usage: workspace-setup.sh <workspace-namespace> <repo> <fork> <token-key> <board> <library>\nset -e\n\nNS=${1:?workspace-setup.sh needs the workspace namespace}\nREPO=${2:?workspace-setup.sh needs the upstream repository}\nFORK=${3:?workspace-setup.sh needs the fork}\n# The Secret key holding the token of the person who pressed the button. The branch is pushed\n# with THEIR credential, to THEIR fork, so the work is attributable to them.\nTOKEN_KEY=${4:?workspace-setup.sh needs the token key}\n# So each step can name itself on the job, and the board can say what it is waiting for rather\n# than showing \"Running\" through five minutes of clone and install.\nBOARD=${5:-}\nLIBRARY=${6:-}\n\nSECRET_NS=vuln-console\nSECRET=settings\nWS=/workspaces/$NS\n\nkube() { KUBECONFIG=/dev/null kubectl \"$@\"; }\n\nstage() {\n  [ -n \"$BOARD\" ] && [ -n \"$LIBRARY\" ] || return 0\n  sh \"$(dirname \"$0\")/job.sh\" \"$BOARD\" \"$LIBRARY\" \"stage=$1\" >/dev/null 2>&1 || true\n}\n\n# Wait for the workspace to exist before trying to talk to it.\n#\n# A workspace is minutes old before it is usable: Fleet has to render the Bundle, the kubelet has\n# to pull node:24, and boot.sh then clones the repository and runs a yarn install. Exec'ing into\n# it before any of that has happened fails with `container not found (\"workspace\")`, which is\n# what the first real run did.\nstage waiting\n# Tested by TRYING it, not by reading a status. What this needs is to be able to exec into the\n# container and find the checkout; both readiness conditions available here mean something else.\n# `readyReplicas` and the container's `ready` are both the startup probe, which is the DEV SERVER\n# answering on 8005 - the last thing to start and, for a repository whose dev server does not\n# build, something that may never happen. A fix does not need a dev server to bump a lockfile, so\n# waiting on one would fail every run on such a repository for a reason unrelated to the work.\necho \"workspace-setup.sh: waiting for $NS to be usable\"\ni=0\nok=no\nwhile [ \"$i\" -lt 240 ]; do\n  if kube exec -n \"$NS\" \"deploy/$NS\" -c workspace -- test -d \"$WS/src/.git\" >/dev/null 2>&1; then\n    ok=yes\n    break\n  fi\n  i=$((i + 1))\n  sleep 5\ndone\n\nif [ \"$ok\" != yes ]; then\n  echo \"workspace-setup.sh: $NS did not become usable within 20 minutes\" >&2\n  exit 2\nfi\n\nsecret_key() {\n  kube get secret \"$2\" -n \"$1\" -o \"jsonpath={.data.$3}\" 2>/dev/null | base64 -d 2>/dev/null | tr -d '\\r\\n'\n}\n\nGH_TOKEN=$(secret_key \"$SECRET_NS\" \"$SECRET\" \"$TOKEN_KEY\")\n\nif [ -z \"$GH_TOKEN\" ]; then\n  echo \"workspace-setup.sh: no GitHub token is stored for this user, so nothing could be pushed\" >&2\n  exit 2\nfi\n\nstage preparing\n\n# The fork has to exist before the agent needs it. Creating it is one call and it is idempotent;\n# discovering it is missing happens at `git push`, three minutes into a run, after the work.\nFORK_OWNER=${FORK%%/*}\nFORK_NAME=${FORK##*/}\n\nstatus=$(curl -s -o /dev/null -w '%{http_code}' \\\n  -H \"Authorization: Bearer $GH_TOKEN\" -H \"Accept: application/vnd.github+json\" \\\n  \"https://api.github.com/repos/$FORK_OWNER/$FORK_NAME\")\n\nif [ \"$status\" = \"404\" ]; then\n  echo \"workspace-setup.sh: $FORK does not exist yet - forking $REPO\"\n  curl -s -o /dev/null -X POST \\\n    -H \"Authorization: Bearer $GH_TOKEN\" -H \"Accept: application/vnd.github+json\" \\\n    \"https://api.github.com/repos/$REPO/forks\"\n  # A fork is created asynchronously; it is usually there within a few seconds.\n  i=0\n  while [ \"$i\" -lt 30 ]; do\n    status=$(curl -s -o /dev/null -w '%{http_code}' \\\n      -H \"Authorization: Bearer $GH_TOKEN\" -H \"Accept: application/vnd.github+json\" \\\n      \"https://api.github.com/repos/$FORK_OWNER/$FORK_NAME\")\n    [ \"$status\" = \"200\" ] && break\n    i=$((i + 1))\n    sleep 2\n  done\nfi\n\n[ \"$status\" = \"200\" ] || { echo \"workspace-setup.sh: $FORK is not reachable (HTTP $status)\" >&2; exit 2; }\n\n# Everything below runs inside the workspace, as its own user, reading the token off stdin.\nprintf '%s' \"$GH_TOKEN\" | kube exec -i -n \"$NS\" \"deploy/$NS\" -c workspace -- \\\n  setpriv --reuid=1000 --regid=1000 --init-groups \\\n  /usr/bin/env WS=\"$WS\" FORK=\"$FORK\" REPO=\"$REPO\" /bin/sh -s <<'INNER'\nset -e\nTOKEN=$(cat)\nmkdir -p \"$WS/bin\"\n\n# git, for the push. A credential store file rather than a URL with the token embedded in it:\n# a remote carrying a token is a token in `git remote -v`, in every error message, and in the\n# repository's own config on disk.\numask 077\nprintf 'https://x-access-token:%s@github.com\\n' \"$TOKEN\" > \"$WS/.git-credentials\"\ngit config --global credential.helper \"store --file=$WS/.git-credentials\"\ngit config --global user.name \"${GIT_NAME:-Vulnerability Console}\"\ngit config --global user.email \"${GIT_EMAIL:-noreply@rancher.com}\"\n\n# Never attribute a console fix to the agent. The commits are the human's, opened on their fork.\ngit config --global --unset-all trailer.co-authored-by 2>/dev/null || true\n\n# gh, which the fix prompt uses to read alerts and list pull requests. Not in the image and not\n# in Debian's repositories, so the released static binary.\nif ! [ -x \"$WS/bin/gh\" ]; then\n  GH_VERSION=2.76.1\n  ARCH=$(uname -m)\n  case \"$ARCH\" in\n    x86_64) GH_ARCH=amd64 ;;\n    aarch64|arm64) GH_ARCH=arm64 ;;\n    *) GH_ARCH=amd64 ;;\n  esac\n  URL=\"https://github.com/cli/cli/releases/download/v${GH_VERSION}/gh_${GH_VERSION}_linux_${GH_ARCH}.tar.gz\"\n  curl -sL \"$URL\" -o /tmp/gh.tgz\n  tar -xzf /tmp/gh.tgz -C /tmp\n  mv \"/tmp/gh_${GH_VERSION}_linux_${GH_ARCH}/bin/gh\" \"$WS/bin/gh\"\n  chmod 755 \"$WS/bin/gh\"\n  rm -rf /tmp/gh.tgz \"/tmp/gh_${GH_VERSION}_linux_${GH_ARCH}\"\nfi\n\n# gh reads GH_TOKEN from the environment; the shell wrapper sources this for every command the\n# agent runs. 0600, because it is a token in a file.\nprintf 'GH_TOKEN=%s\\nGITHUB_TOKEN=%s\\nVULN_FORK=%s\\nVULN_REPO=%s\\n' \"$TOKEN\" \"$TOKEN\" \"$FORK\" \"$REPO\" > \"$WS/.env\"\nchmod 600 \"$WS/.env\"\n\necho \"workspace-setup: credential, gh $(\"$WS/bin/gh\" --version | head -1 | awk '{print $3}') and $FORK ready\"\nINNER\n",
};
